    private fun hash(s: String): Long {
        var h = 0x811c9dc5L
        for (ch in s) {
            h = h xor ch.code.toLong()
            h = (h * 0x01000193L) and 0xFFFFFFFFL
        }
        return h
    }

    /** Same rule as the web and iPhone: the cover the story carries, else the Discovery one, else one picked from its key. */
    fun look(key: String, extra: String?): CoverLook {
        try {
            val c = JSONObject(extra ?: "{}").optJSONObject("cover")
            val kind = c?.optString("kind").orEmpty()
            val color = c?.optString("color").orEmpty()
            if (kind in KINDS && Regex("^#[0-9a-fA-F]{6}$").matches(color)) return CoverLook(kind, color.uppercase())
        } catch (e: Exception) { /* no cover carried */ }
        FIXED[key]?.let { return CoverLook(it.first, it.second) }
        val h = hash(key.ifBlank { "story" })
        return CoverLook(KINDS[(h % KINDS.size).toInt()], COLORS[((h ushr 8) % COLORS.size).toInt()])
    }

    fun color(hex: String): Color = try { Color(android.graphics.Color.parseColor(hex)) } catch (e: Exception) { Color(0xFF4DB6A6) }
}

/** A story cover: the ground (halo of the story colour, dark vignette), the motif fitted in the middle, a thin frame when big enough. */
@Composable
fun StoryCover(look: CoverLook, modifier: Modifier = Modifier, framed: Boolean = true) {
    val c = remember(look.color) { Covers.color(look.color) }
    val shapes = Covers.MOTIFS[look.kind] ?: Covers.MOTIFS.getValue("bard")
    Box(modifier) {
        Canvas(Modifier.fillMaxSize()) {
            val w = size.width
            val h = size.height
            drawRect(Covers.GROUND)
            drawRect(
                Brush.radialGradient(
                    0f to c.copy(alpha = 0.22f), 0.55f to c.copy(alpha = 0.06f), 1f to Color.Transparent,
                    center = Offset(w / 2f, h / 2f), radius = maxOf(w * 0.42f, h * 0.7f),
                )
            )
            drawRect(
                Brush.radialGradient(
                    0.55f to Color.Transparent, 1f to Color.Black.copy(alpha = 0.45f),
                    center = Offset(w / 2f, h / 2f), radius = maxOf(w, h) * 0.75f,
                )
            )
            val k = minOf(w / 320f, h / 140f)
            translate((w - 320f * k) / 2f, (h - 140f * k) / 2f) {
                scale(k, k, pivot = Offset.Zero) {
                    shapes.forEach { s ->
                        translate(s.tx, s.ty) {
                            rotate(s.rot, pivot = Offset.Zero) {
                                scale(s.sc, s.sc, pivot = Offset.Zero) {
                                    if (s.fill != 0) drawPath(s.path, paintOf(s.fill, c), alpha = s.fillA, style = Fill)
                                    if (s.stroke != 0) drawPath(
                                        s.path, paintOf(s.stroke, c), alpha = s.strokeA,
                                        style = Stroke(
                                            width = s.width, cap = StrokeCap.Round, join = StrokeJoin.Round,
                                            pathEffect = s.dash?.let { PathEffect.dashPathEffect(it) },
                                        ),
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
        if (framed) Box(Modifier.fillMaxSize().padding(6.dp).border(1.dp, Covers.GOLD.copy(alpha = 0.22f), RoundedCornerShape(9.dp)))
    }
}

private fun paintOf(role: Int, c: Color): Color = when (role) {
    1 -> c
    2 -> Covers.GOLD
    3 -> Covers.PALE
    4 -> Covers.GROUND
    else -> Covers.CREAM
}
